assignments.referenceSolution:
`Field` is a data descriptor that delegates the check to `validate` and stores the clean value in the instance `__dict__` under its own name. Because it defines `__set__`, reads always route through `__get__`, so writing directly to `__dict__` cannot hide it. Subclasses implement only `validate`.

**`fields.py`**

```python
from __future__ import annotations

from collections.abc import Container
from typing import Any, Generic, TypeVar

T = TypeVar("T")


class ValidationError(ValueError):
    """Raised when a field rejects a value."""


class Field(Generic[T]):
    """Data descriptor that validates on write and stores in the instance __dict__."""

    name: str

    def __set_name__(self, owner: type, name: str) -> None:
        self.name = name

    def validate(self, value: Any) -> T:
        raise NotImplementedError

    def __get__(self, obj: object | None, objtype: type | None = None) -> Any:
        if obj is None:
            return self
        try:
            return obj.__dict__[self.name]
        except KeyError:
            raise AttributeError(self.name) from None

    def __set__(self, obj: object, value: Any) -> None:
        obj.__dict__[self.name] = self.validate(value)

    def __delete__(self, obj: object) -> None:
        try:
            del obj.__dict__[self.name]
        except KeyError:
            raise AttributeError(self.name) from None


class BoundedFloat(Field[float]):
    def __init__(self, low: float, high: float) -> None:
        self.low, self.high = low, high

    def validate(self, value: Any) -> float:
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise ValidationError(f"{self.name} must be a number, got {value!r}")
        if not self.low <= value <= self.high:
            raise ValidationError(
                f"{self.name} must be between {self.low} and {self.high}, got {value}"
            )
        return float(value)


class BoundedInt(Field[int]):
    def __init__(self, low: int, high: int) -> None:
        self.low, self.high = low, high

    def validate(self, value: Any) -> int:
        if isinstance(value, bool) or not isinstance(value, int):
            raise ValidationError(f"{self.name} must be an int, got {value!r}")
        if not self.low <= value <= self.high:
            raise ValidationError(
                f"{self.name} must be between {self.low} and {self.high}, got {value}"
            )
        return value


class OneOf(Field[str]):
    def __init__(self, choices: Container[str]) -> None:
        self.choices = choices

    def validate(self, value: Any) -> str:
        if value not in self.choices:
            raise ValidationError(f"{self.name} must be one of {self.choices}, got {value!r}")
        return value


class CompletionSettings:
    temperature = BoundedFloat(0.0, 2.0)
    max_tokens = BoundedInt(1, 128_000)
    model = OneOf(("small", "large"))

    def __init__(self, temperature: float, max_tokens: int, model: str) -> None:
        self.temperature = temperature
        self.max_tokens = max_tokens
        self.model = model
```

**`test_fields.py`**

```python
import pytest

from fields import BoundedFloat, CompletionSettings, ValidationError


def test_valid_values_are_stored_per_instance() -> None:
    a = CompletionSettings(0.2, 100, "small")
    b = CompletionSettings(1.5, 4000, "large")
    assert (a.temperature, a.max_tokens, a.model) == (0.2, 100, "small")
    assert (b.temperature, b.max_tokens, b.model) == (1.5, 4000, "large")
    assert a.__dict__ == {"temperature": 0.2, "max_tokens": 100, "model": "small"}


def test_ints_are_coerced_to_float() -> None:
    s = CompletionSettings(1, 10, "small")
    assert s.temperature == 1.0 and isinstance(s.temperature, float)


@pytest.mark.parametrize(
    "kwargs, fragment",
    [
        ({"temperature": 3.0, "max_tokens": 10, "model": "small"}, "temperature"),
        ({"temperature": 0.5, "max_tokens": 0, "model": "small"}, "max_tokens"),
        ({"temperature": 0.5, "max_tokens": 10, "model": "huge"}, "model"),
        ({"temperature": True, "max_tokens": 10, "model": "small"}, "temperature"),
        ({"temperature": 0.5, "max_tokens": 10.5, "model": "small"}, "max_tokens"),
    ],
)
def test_invalid_values_raise_validation_error(kwargs: dict, fragment: str) -> None:
    with pytest.raises(ValidationError, match=fragment):
        CompletionSettings(**kwargs)


def test_data_descriptor_beats_instance_dict() -> None:
    s = CompletionSettings(0.5, 10, "small")
    s.__dict__["temperature"] = 99.0  # bypasses validation, but reads still go via __get__
    assert s.temperature == 99.0
    with pytest.raises(ValidationError):
        s.temperature = 99.0


def test_class_access_returns_descriptor_and_names_are_set() -> None:
    field = CompletionSettings.temperature
    assert isinstance(field, BoundedFloat)
    assert field.name == "temperature"


def test_unset_attribute_and_delete() -> None:
    s = CompletionSettings(0.5, 10, "small")
    del s.model
    with pytest.raises(AttributeError):
        s.model
    with pytest.raises(AttributeError):
        del s.model
```

