assignments.referenceSolution:
The descriptor looks the value up in `obj.__dict__`, and on a miss takes a lock, re-checks, computes, and stores. A shared `RLock` per descriptor is simple; the cost is that different instances serialize on first access, which is why CPython 3.12 dropped the lock from `cached_property`, and why a per-instance lock is the next refinement if contention matters. The class never defines `__set__`, so it remains non-data.

**`lazy.py`**

```python
from __future__ import annotations

import threading
from collections.abc import Callable
from typing import Any, Generic, TypeVar, overload

T = TypeVar("T")
_UNSET = object()


class lazy(Generic[T]):
    """Non-data descriptor: compute once per instance, thread-safely, cache in __dict__."""

    def __init__(self, func: Callable[[Any], T]) -> None:
        self.func = func
        self.attrname: str | None = None
        self.__doc__ = func.__doc__
        self._lock = threading.RLock()

    def __set_name__(self, owner: type, name: str) -> None:
        if self.attrname is None:
            self.attrname = name
        elif name != self.attrname:
            raise TypeError(
                f"Cannot assign the same lazy to two names: {self.attrname!r} and {name!r}"
            )

    @overload
    def __get__(self, obj: None, objtype: type | None = None) -> "lazy[T]": ...
    @overload
    def __get__(self, obj: object, objtype: type | None = None) -> T: ...
    def __get__(self, obj: object | None, objtype: type | None = None) -> Any:
        if obj is None:
            return self
        if self.attrname is None:
            raise TypeError("lazy used without __set_name__")
        cache = obj.__dict__
        value = cache.get(self.attrname, _UNSET)
        if value is _UNSET:
            with self._lock:
                value = cache.get(self.attrname, _UNSET)  # double-checked
                if value is _UNSET:
                    value = self.func(obj)  # exceptions propagate and are not cached
                    cache[self.attrname] = value
        return value
```

**`test_lazy.py`**

```python
import threading

import pytest

from lazy import lazy


class Report:
    def __init__(self) -> None:
        self.calls = 0

    @lazy
    def total(self) -> int:
        self.calls += 1
        return 42

    @lazy
    def flaky(self) -> int:
        self.calls += 1
        if self.calls < 3:
            raise RuntimeError("not yet")
        return self.calls


def test_computed_once_and_cached_in_dict() -> None:
    r = Report()
    assert r.total == 42 and r.total == 42
    assert r.calls == 1
    assert r.__dict__["total"] == 42


def test_per_instance_isolation() -> None:
    a, b = Report(), Report()
    a.total
    assert a.calls == 1 and b.calls == 0


def test_class_access_returns_descriptor() -> None:
    assert isinstance(Report.total, lazy)
    assert Report.total.attrname == "total"


def test_delete_invalidates_and_assignment_overrides() -> None:
    r = Report()
    r.total
    del r.total
    r.total
    assert r.calls == 2
    r.total = 7  # non-data descriptor: plain assignment wins
    assert r.total == 7


def test_exceptions_are_not_cached() -> None:
    r = Report()
    for _ in range(2):
        with pytest.raises(RuntimeError):
            r.flaky
    assert r.flaky == 3


def test_threads_compute_once() -> None:
    r = Report()
    barrier = threading.Barrier(8)
    results: list[int] = []

    def worker() -> None:
        barrier.wait()
        results.append(r.total)

    threads = [threading.Thread(target=worker) for _ in range(8)]
    for t in threads:
        t.start()
    for t in threads:
        t.join()
    assert results == [42] * 8
    assert r.calls == 1


def test_same_descriptor_under_two_names_is_rejected() -> None:
    with pytest.raises(TypeError, match="two names"):
        class Bad:
            @lazy
            def a(self) -> int:
                return 1

            b = a
```

